import fs from 'node:fs';

const options = JSON.parse(fs.readFileSync(new URL('./provider-options.json', import.meta.url), 'utf8'));

export const apiVersion = 1;

export function generate(context) {
  fs.appendFileSync(options.orderLogPath, 'sdk,');
  fs.appendFileSync(options.logPath, context.input.endsWith('one.json') ? 'SDK-one,' : 'SDK-two,');
  return {
    apiVersion: 1,
    artifacts: [{ path: context.output + '/client.ts', content: '// Generated by @exprtlabs/golem-openapi\nexport {};\n' }],
    manifestPaths: [],
    watchInputs: [context.input],
  };
}
